//! Differential test: the zkVM guest's decision logic (`decide_from_str`, the exact code the guest runs)
//! vs an exact integer reference vs the TypeScript float risk model on the SAME seeded corpus of
//! >= 2000 random + boundary witnesses that the two STARK crates use
//! (`fixtures/differential_corpus.json`, generated by `sdks/stark-pca/tests/gen_differential_corpus.mjs`).
//!
//! The corpus drives the guest through its real input: `risk_inputs_scaled` and `budget_scaled` are set
//! directly, a predicate miss is an action verb outside the grant's predicates, an unsatisfied caveat is a
//! `now` past the grant's `expires`. The committed sample grant additionally carries
//! `max_blast_radius <= 0.5` (a caveat the corpus relation does not model), which is accounted for
//! explicitly below rather than ignored.
//!
//! Known, documented differences (asserted, not hidden): the guest clamps risk inputs into `[0, S]` and
//! has no `bMax` range check (the TS model behaves the same way; only the STARK AIRs refuse
//! out-of-domain witnesses).

use pca_zkvm_core::decide_from_str;
use serde_json::Value;

fn fx(name: &str) -> String {
    let p = std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("../fixtures").join(name);
    std::fs::read_to_string(&p).unwrap_or_else(|e| panic!("{}: {e}", p.display()))
}

const BLAST_CAVEAT_MAX: u64 = 500_000; // the sample grant's max_blast_radius = 0.5 at scale S

#[test]
fn guest_decision_agrees_with_the_exact_reference_and_the_ts_model_on_the_corpus() {
    let corpus: Value = serde_json::from_str(&fx("differential_corpus.json")).unwrap();
    let base: Value = serde_json::from_str(&fx("decide_input.sample.json")).unwrap();
    let theta1 = corpus["policy"]["theta1_scaled"].as_u64().unwrap() as u128;
    assert!(corpus["in_domain_cases"].as_u64().unwrap() >= 2000);

    // control: the untouched sample is allowed (so every denial below is caused by the case)
    assert_eq!(decide_from_str(&base.to_string()).allow, 1);

    let (mut n_in, mut allow, mut deny, mut blast_denied) = (0usize, 0usize, 0usize, 0usize);
    let (mut ood, mut ood_guest_allows, mut ts_strict, mut ts_lenient) = (0usize, 0usize, 0usize, 0usize);
    for c in corpus["cases"].as_array().unwrap() {
        let x: Vec<u64> = c["inputs_scaled"].as_array().unwrap().iter().map(|v| v.as_str().unwrap().parse().unwrap()).collect();
        let b: u64 = c["budget_scaled"].as_str().unwrap().parse().unwrap();
        let (pm, co) = (c["predicate_match"].as_bool().unwrap(), c["caveats_ok"].as_bool().unwrap());
        let mut input = base.clone();
        input["risk_inputs_scaled"] = serde_json::json!(x);
        input["budget_scaled"] = serde_json::json!(b);
        if !pm {
            input["action"]["verb"] = serde_json::json!("delete");
        }
        if !co {
            input["now"] = serde_json::json!(1_760_020_000_000u64);
        }
        let d = decide_from_str(&input.to_string());
        let guest = d.allow == 1;
        let blast_ok = x[2].min(1_000_000) <= BLAST_CAVEAT_MAX;
        let exact = c["exact_allow"].as_bool().unwrap();
        let ts = c["ts_allow"].as_bool().unwrap();
        let raw: u128 = c["exact_rraw"].as_str().unwrap().parse().unwrap();
        if c["in_domain"].as_bool().unwrap() {
            n_in += 1;
            // the guest relation = the corpus relation AND the grant's own blast-radius caveat
            assert_eq!(guest, exact && blast_ok, "{} {:?} B={b} pm={pm} co={co}: guest={guest} exact={exact} blast_ok={blast_ok}", c["class"], x);
            if exact && !blast_ok {
                blast_denied += 1;
            }
            if guest { allow += 1 } else { deny += 1 }
            if ts != exact {
                if ts { ts_lenient += 1 } else { ts_strict += 1 }
                let at_theta = raw == theta1 * 1_000_000;
                let at_budget = (b as u128) * 1_000_000 == raw; // kappa = 1
                assert!(at_theta || at_budget, "TS float differs from exact away from an exact boundary: {} raw={raw} B={b}", c["class"]);
            }
        } else {
            ood += 1;
            // Outside the quantisation domain the guest does not refuse by range: it clamps. It must
            // still equal the relation evaluated on the clamped inputs (and so equal the TS model,
            // which clamps the same way), except for the same float-boundary slack.
            let xc: Vec<u128> = x.iter().map(|v| (*v).min(1_000_000) as u128).collect();
            let w = [250_000u128, 200_000, 200_000, 200_000, 100_000, 50_000];
            let rc: u128 = (0..6).map(|i| w[i] * if i == 1 || i == 4 { 1_000_000 - xc[i] } else { xc[i] }).sum();
            let exp = rc <= theta1 * 1_000_000 && (b as u128) * 1_000_000 >= rc && pm && co && blast_ok;
            assert_eq!(guest, exp, "clamped relation, {} {:?} B={b}", c["class"], x);
            if guest {
                ood_guest_allows += 1;
            }
        }
    }
    assert_eq!(ts_lenient, 0, "TS float model more permissive than the exact relation");
    assert!(n_in >= 2000 && allow > 300 && deny > 400, "corpus not balanced: in={n_in} allow={allow} deny={deny}");
    eprintln!(
        "zkvm differential: in-domain {n_in} (allow {allow}, deny {deny}; {blast_denied} denied only by the grant's max_blast_radius caveat) agree with the exact reference; \
         out-of-domain {ood}: guest clamps (allows {ood_guest_allows}) and equals the clamped relation; TS float stricter at an exact boundary: {ts_strict}"
    );
}
